BEGIN TRANSACTION READ ONLY; SET LOCAL statement_timeout = '20s'; WITH targets AS (SELECT c.oid, n.nspname, c.relname, c.relrowsecurity FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='app' AND c.relkind IN ('r','p')), api_roles AS (SELECT rolname FROM pg_roles WHERE rolname IN ('anon','authenticated','service_role')) SELECT jsonb_build_object('transaction_read_only',current_setting('transaction_read_only'),'table_privileges',(SELECT jsonb_agg(jsonb_build_object('schema',t.nspname,'table',t.relname,'role',r.rolname,'schema_usage',has_schema_privilege(r.rolname,t.nspname,'USAGE'),'select',has_table_privilege(r.rolname,t.oid,'SELECT'),'insert',has_table_privilege(r.rolname,t.oid,'INSERT'),'update',has_table_privilege(r.rolname,t.oid,'UPDATE'),'delete',has_table_privilege(r.rolname,t.oid,'DELETE'),'rls_enabled',t.relrowsecurity) ORDER BY t.relname,r.rolname) FROM targets t CROSS JOIN api_roles r),'data_api_database_settings',(SELECT COALESCE(jsonb_agg(jsonb_build_object('database',d.datname,'role',COALESCE(r.rolname,'ALL'),'setting',s.setting)), '[]'::jsonb) FROM pg_db_role_setting dr LEFT JOIN pg_database d ON d.oid=dr.setdatabase LEFT JOIN pg_roles r ON r.oid=dr.setrole CROSS JOIN LATERAL unnest(dr.setconfig) s(setting) WHERE s.setting LIKE 'pgrst.db_schemas=%' OR s.setting LIKE 'pgrst.db_extra_search_path=%'),'current_pgrst_db_schemas',current_setting('pgrst.db_schemas',true),'public_function',(SELECT jsonb_agg(jsonb_build_object('name',p.proname,'return_type',pg_get_function_result(p.oid),'security_definer',p.prosecdef,'anon_execute',has_function_privilege('anon',p.oid,'EXECUTE'),'authenticated_execute',has_function_privilege('authenticated',p.oid,'EXECUTE'),'definition',pg_get_functiondef(p.oid))) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname='rls_auto_enable'),'event_triggers',(SELECT jsonb_agg(jsonb_build_object('name',evtname,'event',evtevent,'enabled',evtenabled,'function',evtfoid::regprocedure::text,'tags',evttags)) FROM pg_event_trigger)) AS access_review; ROLLBACK;
